package com.nigson.acceptance.fulfillment;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
public final class FulfillmentHttpAcceptance {
 private FulfillmentHttpAcceptance(){}
 public static void configure(Map<String,Object> properties){if(System.getenv("NIGSON_TEST_FULFILLMENT")==null)return;properties.put("NIGSON_FULFILLMENT_ENABLED","true");properties.put("NIGSON_FULFILLMENT_MODE","MOCK");properties.put("NIGSON_FULFILLMENT_APPROVAL","SYNTHETIC_CARRIER_NOT_QUALIFIED");properties.put("NIGSON_FULFILLMENT_APPROVAL_UNTIL",Instant.now().plusSeconds(3600).toString());properties.put("NIGSON_FULFILLMENT_MANUAL_CONTINGENCY","SYNTHETIC_MANUAL_CONTINGENCY_NOT_APPROVED");properties.put("NIGSON_FULFILLMENT_TRACKING_HOSTS","tracking.synthetic.invalid");}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base)throws Exception{if(System.getenv("NIGSON_TEST_FULFILLMENT")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var cookies=new ArrayList<String>();var tokens=new ArrayList<String>();try(var f=new ShipmentFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){for(UUID party:List.of(f.inventory.actor.party(),f.inventory.orders.party)){String issuer=f.inventory.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String token=JdbcSessionTrust.opaque();tokens.add(token);String session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,party.toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),token,SessionRecord.TokenState.READY));cookies.add("__Host-nigson-session="+session);}String uri=base+"/api/v1/staff/orders/"+f.order+"/shipments",request=EventCodec.JSON.writeValueAsString(f.input("5","MANUAL","SYNTHETIC_HTTP_RECEIPT"));var node=(tools.jackson.databind.node.ObjectNode)EventCodec.JSON.readTree(request);node.remove("trackingUrl");request=EventCodec.JSON.writeValueAsString(node);assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(request))).statusCode()).isEqualTo(401);assertThat(send(http,command(uri,"POST",cookies.get(1),tokens.get(1),"wrong-role",request,null)).statusCode()).isEqualTo(403);assertThat(send(http,command(uri,"POST",cookies.getFirst(),"wrong","csrf",request,null)).statusCode()).isEqualTo(401);var created=send(http,command(uri,"POST",cookies.getFirst(),tokens.getFirst(),"shipment",request,null));assertThat(created.statusCode()).as("create: %s",created.body()).isEqualTo(201);var shipment=EventCodec.JSON.readTree(created.body());assertThat(shipment.get("status").asString()).isEqualTo("READY");assertThat(created.headers().firstValue("ETag")).hasValue("\"0\"");assertThat(created.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(send(http,command(uri,"POST",cookies.getFirst(),tokens.getFirst(),"shipment",request,null)).body()).isEqualTo(created.body());String id=shipment.get("id").asString(),dispatch=base+"/api/v1/staff/shipments/"+id+"/dispatch",reason="{\"reason\":\"Synthetic physical handover proof\"}";Instant actual=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);String explicit=reason.substring(0,reason.length()-1)+",\"dispatchedAt\":\""+actual+"\"}";assertThat(send(http,command(dispatch,"POST",cookies.getFirst(),tokens.getFirst(),"null-time",reason.replace("}",",\"dispatchedAt\":null}"),0L)).statusCode()).isEqualTo(400);assertThat(send(http,command(dispatch,"POST",cookies.getFirst(),tokens.getFirst(),"future-time",explicit.replace(actual.toString(),actual.plusSeconds(60).toString()),0L)).statusCode()).isEqualTo(422);reason=explicit;var shipped=send(http,command(dispatch,"POST",cookies.getFirst(),tokens.getFirst(),"dispatch",reason,0L));assertThat(shipped.statusCode()).as("dispatch: %s",shipped.body()).isEqualTo(200);assertThat(shipped.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(f.inventory.jdbc.queryForObject("SELECT dispatched_at FROM commerce.shipment WHERE id=?",java.sql.Timestamp.class,UUID.fromString(id)).toInstant()).isEqualTo(actual);assertThat(send(http,command(dispatch,"POST",cookies.getFirst(),tokens.getFirst(),"stale",reason,0L)).statusCode()).isEqualTo(412);String delivery=base+"/api/v1/staff/shipments/"+id+"/delivery",deliveryBody="{\"deliveredAt\":\""+Instant.now()+"\",\"reason\":\"Synthetic actual delivery receipt\"}";var delivered=send(http,command(delivery,"POST",cookies.getFirst(),tokens.getFirst(),"delivery",deliveryBody,1L));assertThat(delivered.statusCode()).as("delivery: %s",delivered.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(delivered.body()).get("status").asString()).isEqualTo("DELIVERED");String returned=base+"/api/v1/staff/orders/"+f.order+"/stock-returns",returnBody="{\"lines\":[{\"orderLineId\":\""+f.line+"\",\"balanceId\":\""+f.balance+"\",\"quantity\":\"2\"}],\"kind\":\"PHYSICAL_RETURN\",\"receiptReference\":\"SYNTHETIC_HTTP_PHYSICAL_RECEIPT\",\"reason\":\"Synthetic verified physical return\"}";var receipt=send(http,command(returned,"POST",cookies.getFirst(),tokens.getFirst(),"return",returnBody,null));assertThat(receipt.statusCode()).as("return: %s",receipt.body()).isEqualTo(201);assertThat(send(http,command(returned,"POST",cookies.getFirst(),tokens.getFirst(),"different-key-same-receipt",returnBody,null)).body()).isEqualTo(receipt.body());assertThat(f.value("on_hand")).isEqualByComparingTo("7");try(var cartFixture=new com.nigson.acceptance.cart.CartFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){var market=cartFixture.f.market;try{String rules=base+"/api/v1/staff/delivery-rules",ruleBody="{\"marketId\":\""+market+"\",\"countryCode\":\"NG\",\"fee\":\"12.34\",\"priority\":0,\"active\":true}";var rule=send(http,command(rules,"POST",cookies.getFirst(),tokens.getFirst(),"rule-create",ruleBody,null));assertThat(rule.statusCode()).as("rule create: %s",rule.body()).isEqualTo(201);assertThat(rule.headers().firstValue("ETag")).hasValue("\"0\"");String ruleId=EventCodec.JSON.readTree(rule.body()).get("id").asString(),updatedBody=ruleBody.replace("12.34","5.00");var updated=send(http,command(rules+"/"+ruleId,"PUT",cookies.getFirst(),tokens.getFirst(),"rule-update",updatedBody,0L));assertThat(updated.statusCode()).as("rule update: %s",updated.body()).isEqualTo(200);assertThat(updated.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(send(http,command(rules+"/"+ruleId,"PUT",cookies.getFirst(),tokens.getFirst(),"rule-stale",updatedBody,0L)).statusCode()).isEqualTo(412);assertThat(send(http,command(rules,"POST",cookies.getFirst(),tokens.getFirst(),"wrong-scale",ruleBody.replace("12.34","12.340"),null)).statusCode()).isEqualTo(422);}finally{cartFixture.f.jdbc.update("DELETE FROM commerce.delivery_rule WHERE market_id=?",market);}}var metrics=app.getBean(io.micrometer.core.instrument.MeterRegistry.class);for(String operation:List.of("RULE_CREATE","RULE_UPDATE","SHIPMENT","DISPATCH","DELIVERY","RETURN"))assertThat(metrics.get("nigson.fulfillment.commands").tag("operation",operation).counter().count()).isEqualTo(1);f.inventory.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='OPERATIONS'",f.inventory.actor.party());assertThat(send(http,command(uri,"POST",cookies.getFirst(),tokens.getFirst(),"shipment",request,null)).statusCode()).isEqualTo(403);}finally{for(String cookie:cookies)sessions.logout(cookie.substring(cookie.indexOf('=')+1));}}
 private static HttpRequest.Builder command(String uri,String method,String cookie,String csrf,String key,String body,Long version){var r=HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key).header("Content-Type","application/json");if(version!=null)r.header("If-Match","\""+version+"\"");return r.method(method,HttpRequest.BodyPublishers.ofString(body));}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
